/**
 * IMAGE LIBRARY
 * ─────────────────────────────────────────────────────────────────────────────
 * Every photo in the template is referenced by a key from this file — no
 * component hard-codes a URL. To use your own photos:
 *
 *   • Replace `src` with your own URL, or with a path inside /public
 *     (e.g. "/images/my-sofa.jpg").
 *   • Or set `imageMode: "placeholder"` in data/site.ts to show the neutral
 *     placeholders generated by `npm run placeholders` (used for the
 *     downloadable package, where demo photos are not redistributed).
 *
 * Demo photos are from Unsplash (https://unsplash.com/license). Sources are
 * listed in CREDITS.md.
 */

export type ImageAsset = {
  src: string;
  /** Describe what the photo shows; screen readers announce it. */
  alt: string;
};

const unsplash = (id: string) => `https://images.unsplash.com/photo-${id}`;

